/* THROWAWAY UI PROTOTYPE. No Swiggy, LLM, payment, storage or nutrition service is connected. All meals, restaurants, ranges and offers below are fictional fixtures. */
const meals = [
  {id:'paneer',name:'Chilli paneer power bowl',restaurant:'The Good Bowl Club',image:1,veg:true,tags:['spicy','filling','cheesy'],menu:219,discount:40,charges:35,price:[209,239],eta:[25,35],cal:[520,640],protein:[29,37],carbs:[56,70],fat:[19,25],label:'Craving match',benefit:'Spicy, filling, and a little comfort-food energy.',compromise:'More fat than the chicken option; protein is a little lower.',description:'Sample paneer, rice, vegetables and chilli sauce. One regular bowl.'},
  {id:'chicken',name:'Lemon chicken & rice',restaurant:'Little Green Kitchen',image:3,veg:false,tags:['bland','filling','protein'],menu:239,discount:40,charges:35,price:[224,254],eta:[20,30],cal:[510,630],protein:[40,48],carbs:[58,68],fat:[12,18],label:'Protein pick',benefit:'A strong protein contribution without a heavy sauce.',compromise:'Milder than your spicy craving, and slightly above the next-meal money guide.',description:'Sample grilled chicken, lemon rice and vegetables. One regular bowl.'},
  {id:'rajma',name:'Rajma rice, the comfort classic',restaurant:'Everyday Tiffin',image:6,veg:true,tags:['spicy','filling'],menu:159,discount:15,charges:30,price:[164,194],eta:[25,35],cal:[520,650],protein:[18,24],carbs:[80,92],fat:[13,19],label:'Budget bestie',benefit:'Keeps more money available for your last meal.',compromise:'Lower protein: you may want a stronger protein option later.',description:'Sample kidney bean curry, rice and a small salad. One regular portion.'},
  {id:'salad',name:'Crunchy chickpea sunshine bowl',restaurant:'Little Green Kitchen',image:2,veg:true,tags:['bland','light','protein'],menu:189,discount:25,charges:35,price:[189,219],eta:[15,25],cal:[400,510],protein:[20,27],carbs:[44,55],fat:[15,20],label:'Quick & light',benefit:'Light, quick, and comfortably under the spending guide.',compromise:'Less filling than a rice bowl; dressing changes the nutrition.',description:'Sample chickpeas, greens, grains and dressing. One salad bowl.'},
  {id:'pizza',name:'Cheesy garden flatbread',restaurant:'Slice of Happy',image:4,veg:true,tags:['cheesy','filling'],menu:269,discount:40,charges:35,price:[254,284],eta:[30,40],cal:[620,780],protein:[24,32],carbs:[70,88],fat:[27,34],label:'Comfort pick',benefit:'Hits the cheesy craving; a sample curd-side deal can lower the bill.',compromise:'Higher calorie range and a longer wait than the bowl options.',description:'Sample vegetable flatbread with cheese. One personal serving.'},
  {id:'tofu',name:'Smoky tofu & sesame greens',restaurant:'The Good Bowl Club',image:5,veg:true,tags:['spicy','light','protein'],menu:209,discount:35,charges:35,price:[194,224],eta:[20,30],cal:[430,540],protein:[26,34],carbs:[37,48],fat:[18,23],label:'Balanced pick',benefit:'A spicy, lighter bowl with room left for later.',compromise:'Less filling; sesame dressing makes the estimate less certain.',description:'Sample tofu, vegetables, grains and sesame sauce. One regular bowl.'},
  {id:'sweet',name:'Berry yoghurt & oat bowl',restaurant:'Morning, Whenever',image:2,veg:true,tags:['sweet','light','protein'],menu:179,discount:20,charges:30,price:[179,209],eta:[15,25],cal:[360,460],protein:[20,28],carbs:[42,56],fat:[12,15],label:'Sweet spot',benefit:'A quick sweet option that leaves plenty of daily budget.',compromise:'May feel more like a snack than a full meal.',description:'Sample yoghurt, berries, oats and seeds. One breakfast-sized bowl.'},
  {id:'wrap',name:'Pepper chicken grain bowl',restaurant:'Everyday Tiffin',image:3,veg:false,tags:['spicy','filling','protein'],menu:199,discount:30,charges:35,price:[189,219],eta:[20,30],cal:[490,620],protein:[34,43],carbs:[52,65],fat:[15,21],label:'Protein value',benefit:'A spicy protein option close to your next-meal money guide.',compromise:'Portion and sauce can move calories toward the upper estimate.',description:'Sample pepper chicken, grains and vegetables. One regular bowl.'}
];
const mealById = id => meals.find(m => m.id === id);
const image = m => `assets/meal-${m.image}.jpg`;
const names = {a:'Companion',b:'Pocket',c:'Daybook'};
const isReviewEnvironment = location.protocol === 'file:' || ['localhost', '127.0.0.1', '[::1]'].includes(location.hostname) || new URLSearchParams(location.search).get('review') === '1';
let variant = new URLSearchParams(location.search).get('variant') || 'a';
if (!names[variant]) variant = 'a';
const initialState = () => ({stage:'discover',goals:{cal:2200,protein:140,carbs:250,fat:70},intake:{cal:[760,760],protein:[42,42],carbs:[90,90],fat:[25,25]},allowance:600,spent:160,opportunities:2,tastes:['spicy'],highProtein:true,vegOnly:false,cheapOnly:false,fast:false,passed:[],finalists:[],saved:['rajma'],drawMap:[],chosenIndex:null,winner:null,winnerMode:'draw',addon:false,orders:[],message:'You have room for two more meals. Let’s find something you’ll actually enjoy.',receipt:'',lastChange:'Sample day loaded. Nothing has been ordered or eaten here.'});
let state = initialState();
let history = [], timerEpoch = 0, isListening = false, isSpeaking = false, recognition = null, audioContext = null, micStream = null, meterFrame = null, noticeTimer;
const clone = value => JSON.parse(JSON.stringify(value));
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mean = range => (range[0]+range[1])/2;
const rangeText = (r, round=1) => {const a=Math.round(r[0]/round)*round,b=Math.round(r[1]/round)*round;return a===b?`${a}`:`${a}–${b}`;};
const moneyLeft = () => state.allowance-state.spent;
const reducedMotion = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
function nutrition(m,addon=false){const result={};for(const key of ['cal','protein','carbs','fat'])result[key]=[...m[key]];if(addon){const side={cal:[80,110],protein:[6,9],carbs:[8,12],fat:[2,4]};for(const key of Object.keys(side))result[key]=result[key].map((v,i)=>v+side[key][i]);}return result;}
function reserved(key){return state.orders.reduce((r,o)=>{const n=nutrition(mealById(o.meal),o.addon)[key];return [r[0]+n[0]*(1-o.logged),r[1]+n[1]*(1-o.logged)];},[0,0]);}
function remaining(key,includeReserved=false){const r=reserved(key);return [state.goals[key]-state.intake[key][1]-(includeReserved?r[1]:0),state.goals[key]-state.intake[key][0]-(includeReserved?r[0]:0)];}
function pool(){if(state.opportunities<=0)return[];const guide=Math.max(1,state.opportunities);return meals.filter(m=>!state.passed.includes(m.id)&&!state.finalists.includes(m.id)&&(!state.vegOnly||m.veg)&&(!state.cheapOnly||m.price[1]<=250)&&m.price[0]<=moneyLeft()).map(m=>({m,score:state.tastes.filter(t=>m.tags.includes(t)).length*24+(state.highProtein?mean(m.protein)*.8:0)+(state.fast?40-mean(m.eta):0)-(Math.abs(mean(m.cal)-mean(remaining('cal',true))/guide)/70)-(Math.max(0,mean(m.price)-moneyLeft()/guide)/5)+(state.saved.includes(m.id)?5:0)})).sort((a,b)=>b.score-a.score).map(x=>x.m);}
function snapshot(){history.push(clone(state));if(history.length>25)history.shift();}
function change(fn,label){snapshot();fn();state.lastChange=label;render();}
function notify(message){const el=document.getElementById('notice');el.textContent=message;el.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function steps(){const step=state.stage==='discover'||state.stage==='favorites'?1:['ready','concealing','shuffling','draw','revealing'].includes(state.stage)?2:3;return `<div class="journey-steps"><span class="${step===1?'current':''}"><b>1</b> Find your three</span><span>·</span><span class="${step===2?'current':''}"><b>2</b> Let luck choose</span><span>·</span><span class="${step===3?'current':''}"><b>3</b> Make it yours</span></div>`;}
function orb(compact=false){return `<div class="orb-wrap ${isListening?'listening':''} ${isSpeaking?'speaking':''}" ${compact?'aria-hidden="true"':''}><div class="orb" aria-hidden="true"></div></div>`;}
function companion(){return `<section class="panel companion ${isListening?'listening':''} ${isSpeaking?'speaking':''}"><span class="eyebrow">YOUR LITTLE FOOD COPILOT</span>${orb()}<h3>Hey, hungry human.</h3><p class="companion-message" aria-live="polite">${escapeHTML(state.message)}</p><div class="wave" aria-hidden="true">${'<span></span>'.repeat(17)}</div><div class="orb-controls"><button class="mic ${isListening?'active':''}" data-action="mic" aria-label="${isListening?'Stop listening':'Speak to the orb'}" title="Speak to the orb">${isListening?'■':'<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg>'}</button><button class="mic" data-action="speak" aria-label="Hear my day" title="Hear my day"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 9h4l5-4v14l-5-4H4zM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/></svg></button></div><form class="chat-form"><input aria-label="Tell Hungii about your day or craving" placeholder="Tell me what sounds good…" autocomplete="off"><button aria-label="Send message" type="submit">↑</button></form><div class="examples"><button data-action="example" data-text="I have ₹350 left">₹350 left today</button><button data-action="example" data-text="I have 1 meal left">One meal left</button><button data-action="example" data-text="Something cheesy">Feeling cheesy</button><button data-action="example" data-text="I had 2 eggs">Had two eggs</button></div>${state.receipt?`<div class="receipt">${escapeHTML(state.receipt)} <button class="text-button" data-action="undo" ${!history.length?'disabled':''}>Undo</button></div>`:''}<p class="sample-note">Scripted prototype conversation. Voice uses your browser when supported.</p></section>`;}
function tracker(){const kcal=remaining('cal'),reserve=reserved('cal');return `<section class="panel"><div class="row"><h3 class="today-title">Your day, so far</h3><button class="icon-button" data-action="edit-budget" aria-label="Edit daily targets">↗</button></div><p class="small muted">Flexible plans. No perfect timing needed.</p><div class="daily-row"><div class="daily-label"><span>Calories left</span><span>~</span></div><div class="daily-number">${rangeText(kcal,10)}<small>kcal</small></div><div class="progress"><i style="width:${Math.min(100,Math.max(0,mean(state.intake.cal)/state.goals.cal*100))}%"></i></div><p class="small muted">${rangeText(state.intake.cal,10)} of ${state.goals.cal} consumed</p><div class="mini-macros">${[['protein','Protein'],['carbs','Carbs'],['fat','Fat']].map(([k,label])=>`<div><b>${rangeText(remaining(k))}<span class="muted">g</span></b><small>${label} left</small><small style="display:block;margin-top:4px">${rangeText(state.intake[k])}g eaten</small></div>`).join('')}</div></div><div class="balance"><div class="daily-label"><span>Food allowance left</span><span>↗</span></div><div class="daily-number">₹${moneyLeft()}<small>of ₹${state.allowance}</small></div><p class="small">₹${state.spent} spent · checkout charges count, too.</p></div><div class="opportunities">${'<span class="opportunity-dot"></span>'.repeat(Math.min(5,state.opportunities))}<span>${state.opportunities} eating opportunit${state.opportunities===1?'y':'ies'} left</span></div>${reserve[1]>0?`<p class="reserved-note">${rangeText(reserve,10)} kcal reserved for food not yet logged as eaten.</p>`:''}</section>`;}
function finalists(){return `<section class="panel finalist-panel"><div class="row finalist-title"><h3>Your finalists</h3><b>${state.finalists.length}/3</b></div>${[0,1,2].map(i=>{const m=mealById(state.finalists[i]);return `<div class="finalist-slot ${m?'filled':''}">${m?`<img src="${image(m)}" alt=""><div class="slot-text"><strong>${m.name}</strong>₹${rangeText(m.price)} est.</div><button class="slot-remove" data-action="remove" data-id="${m.id}" aria-label="Remove ${m.name}" ${['concealing','shuffling','draw','revealing'].includes(state.stage)?'disabled':''}>×</button>`:`<span class="slot-number">${i+1}</span><span class="slot-text">Someone delicious</span>`}</div>`;}).join('')}<button class="primary" data-action="finalists" ${!state.finalists.length||['concealing','shuffling','draw','revealing'].includes(state.stage)?'disabled':''}>${state.finalists.length===3?'Meet my finalists':'Continue with '+state.finalists.length}<span>↗</span></button><p class="small muted">A like is a maybe. Never an order.</p></section>`;}
function filters(){return `<div class="filters">${[['spicy','Spicy ✧',state.tastes.includes('spicy')],['protein','High protein',state.highProtein],['cheap','Under ₹250',state.cheapOnly],['veg','Veg only',state.vegOnly],['fast','Quick delivery',state.fast]].map(([key,label,active])=>`<button class="chip ${active?'selected':''}" data-action="filter" data-filter="${key}" aria-pressed="${active}">${label}</button>`).join('')}</div>`;}
function macros(m,addon=false){const n=nutrition(m,addon);return `<div class="macro-grid">${[['cal','kcal',60],['protein','protein · g',5],['carbs','carbs · g',8],['fat','fat · g',3]].map(([key,label,divisor])=>`<div><span class="value">${rangeText(n[key])}</span><small>${label}</small><div class="stat-line"><i style="width:${Math.min(100,mean(n[key])/(state.goals[key]/Math.max(1,state.opportunities))*100)}%"></i></div></div>`).join('')}</div><div class="nutrition-note">Sample nutrition ranges · one portion</div>`;}
function mealCard(m,mode='deck'){const isWinner=mode!=='deck';const completedView=mode==='ordered'||mode==='eaten';const displayBill=mode==='review'?sampleBill(m):completedView?state.orders.at(-1):null;const n=nutrition(m,state.addon&&mode!=='deck');const afterCal=[remaining('cal')[0]-n.cal[1],remaining('cal')[1]-n.cal[0]];const afterProtein=[remaining('protein')[0]-n.protein[1],remaining('protein')[1]-n.protein[0]];const trade=moneyLeft()-m.price[1]<0?`Upper price estimate is ₹${m.price[1]-moneyLeft()} beyond today's remaining allowance.`:m.compromise;return `<article class="meal-card ${isWinner?'winner-card':''}" ${mode==='deck'?'id="active-card"':''}>${isWinner?`<div class="winner-banner">✦ ${mode==='ordered'||mode==='eaten'?'Your sample meal':state.winnerMode==='draw'?'Your lucky pick. Your call to keep it.':'Your chosen finalist.'}</div>`:''}<div class="meal-image"><img src="${image(m)}" alt="Illustrative stock food photograph, not the actual sample meal" draggable="false"><div class="image-pills"><span class="pill">${m.veg?'● Veg':'◉ Non-veg'} · ${m.label}</span><button class="save ${state.saved.includes(m.id)?'saved':''}" data-action="save" data-id="${m.id}" aria-label="${state.saved.includes(m.id)?'Unsave':'Save'} ${m.name}" aria-pressed="${state.saved.includes(m.id)}">${state.saved.includes(m.id)?'♥':'♡'}</button></div><span class="image-caption">Illustrative photo · sample meal</span></div><div class="meal-body"><div class="restaurant"><span>${m.restaurant}</span><span>One portion</span></div><h3>${m.name}</h3><div class="meal-price-row"><div class="price">₹${displayBill?displayBill.total:rangeText(m.price)}<small>${displayBill?'sample bill':'checkout est.'}</small></div><span class="eta">◷ ${rangeText(m.eta)} min</span></div>${macros(m,state.addon&&mode!=='deck')}<div class="trade-off"><span class="dot">+</span><span>${m.benefit}</span></div><div class="trade-off compromise"><span class="dot">~</span><span>${trade}</span></div><details class="meal-details"><summary>${completedView?'Your current day ↗':'What this leaves for later ↗'}</summary>${completedView?`<p>Your tracker currently has ${rangeText(remaining('cal'),10)} kcal and ${rangeText(remaining('protein'))} g protein remaining. ₹${moneyLeft()} left after recorded spending. ${state.opportunities} eating opportunities left.</p>`:`<p>${rangeText(afterCal,10)} kcal and ${rangeText(afterProtein)} g protein left after eating. ${displayBill?'₹'+(moneyLeft()-displayBill.total):'Approximately ₹'+(moneyLeft()-m.price[1])+'–'+(moneyLeft()-m.price[0])} left after paying. ${Math.max(0,state.opportunities-1)} further eating opportunit${state.opportunities-1===1?'y':'ies'} planned.</p>`}<p>${m.description} These ranges and offers are invented for interaction design. A real app would need a portion-matched nutrition source and a live cart price.</p></details>${mode==='revealed'?`<button class="primary" data-action="review">Let's have this <span>↗</span></button><button class="text-button" data-action="view-finalists">View my finalists instead</button>`:mode==='review'?billView(m):mode==='ordered'||mode==='eaten'?orderView(m):''}</div>${mode==='deck'?'<span class="swipe-stamp" aria-hidden="true"></span>':''}</article>`;}
function discovery(){const candidates=pool(),m=candidates[0];return `<div class="decision-head"><div class="row"><span class="eyebrow">ROUND 01 · FIND YOUR THREE</span><span class="small muted">${candidates.length} options left</span></div><h2>A meal you’d swipe right on.</h2><p class="small muted">Keep three you’d happily eat. We’ll handle the final coin toss.</p></div>${filters()}${m?`<div class="stack">${mealCard(m)}</div><div class="deck-controls"><div><button class="round-button undo" data-action="undo" aria-label="Undo last action" ${!history.length?'disabled':''}>↶</button><div class="control-label">undo</div></div><div><button class="round-button" data-action="pass" aria-label="Pass on this meal">×</button><div class="control-label">not today</div></div><div><button class="round-button like" data-action="like" aria-label="Shortlist this meal">♡</button><div class="control-label">yes, maybe</div></div></div><p class="deck-caption">Swipe the card, or use the buttons. No pressure, no endless scroll.</p>`:`<div class="empty-state"><h2>${state.opportunities<=0?'Your plan is complete.':'That’s this little batch.'}</h2><p>${state.finalists.length?'You can continue with the meals you liked, or change your preferences.':'Try a different craving or update your allowance. We won’t sneak past your filters.'}</p>${state.finalists.length?'<button class="primary" data-action="finalists">See my finalists ↗</button>':'<button class="primary" data-action="edit-budget">Adjust my day ↗</button>'}<button class="text-button" data-action="revisit">Revisit passed meals</button></div>`}`;}
function drawView(){const stage=state.stage,ready=stage==='ready',draw=stage==='draw',revealing=stage==='revealing';const ids=ready?state.finalists:state.drawMap;return `<section class="draw-view"><div class="decision-head"><span class="eyebrow">ROUND 02 · A LITTLE SERENDIPITY</span><h2>${ready?'You’ve got good taste.':revealing?'A little reveal…':draw?'Trust your gut. Pick one.':'Letting luck do its thing…'}</h2><p class="small muted">${ready?'These all made your shortlist. Turn them over, mix them up, and let a little luck decide.':draw?'Same meals. Equal chances. No wrong card.':'Your finalists stay the same. We’re just mixing their places.'}</p></div><div class="draw-board ${stage==='shuffling'?'shuffle':''}">${ids.map((id,i)=>{const m=mealById(id),showFace=ready||(revealing&&i===state.chosenIndex);return `<button class="draw-card ${!showFace?'hidden':''} ${stage==='concealing'?'flipping':''} ${revealing?(i===state.chosenIndex?'selected':'not-selected'):''}" data-action="${ready?'manual-pick':'pick'}" data-index="${i}" data-id="${ready?id:''}" aria-label="${ready?'Choose '+m.name:revealing&&i===state.chosenIndex?m.name:'Pick card '+(i+1)}" ${ready||draw?'':'disabled'}>${showFace?`<span class="front"><img src="${image(m)}" alt=""><strong>${m.name}</strong><small>₹${rangeText(m.price)} est.</small></span>`:'<span class="back"><span class="card-orbit"><strong>h.</strong></span><span class="wordmark">HUNGII</span></span>'}</button>`;}).join('')}</div><div class="draw-cta">${ready?'<button class="primary" data-action="shuffle">Shuffle my finalists <span>✦</span></button><span class="small muted">Or tap a face-up meal to choose it yourself.</span>':draw?'<span class="pill purple">Your choice is hiding in plain sight.</span>':'<span class="pill purple">'+(revealing?'Your meal is coming into view.':'Cards are mixing…')+'</span>'}<button class="text-button" data-action="change-finalists" ${['concealing','shuffling','revealing'].includes(stage)?'disabled':''}>Change my finalists</button></div><p class="draw-hint">The draw never places an order. You’ll review your pick first.</p></section>`;}
function sampleBill(m){const extra=state.addon?40:0;const discount=state.addon&&m.menu+extra>=300?100:m.discount;return {items:m.menu+extra,charges:m.charges,discount,total:m.menu+extra+m.charges-discount};}
function billView(m){const b=sampleBill(m),base=m.menu+m.charges-m.discount,deal=m.menu+40>=300&&m.menu+40+m.charges-100<base;return `<div class="bill"><span class="eyebrow">SIMULATED CHECKOUT · NO REAL CART</span><div class="row"><span>Meal${state.addon?' + curd side':''}</span><span>₹${b.items}</span></div><div class="row"><span>Delivery & other charges</span><span>₹${b.charges}</span></div><div class="row discount"><span>Sample coupon</span><span>−₹${b.discount}</span></div><div class="row total"><span>Sample payable total</span><span>₹${b.total}</span></div><p class="small muted">This fixture bill demonstrates verification. No offer or price has been checked with Swiggy.</p></div>${deal?`<label class="offer-option"><input type="checkbox" id="offer-side" ${state.addon?'checked':''}><span><strong>A useful side, a smaller bill.</strong><br>Add a sample ₹40 curd side to cross ₹300 and unlock ₹100 off. That saves ₹${base-(m.menu+40+m.charges-100)} overall. Its sample nutrition is included above when selected.</span></label>`:''}<p class="small muted" style="margin-top:14px">₹${moneyLeft()-b.total} would remain today. Paying reserves this meal; it won’t count as eaten yet.</p>${b.total>moneyLeft()?'<p class="receipt">This sample checkout exceeds your allowance. Adjust your day or revisit your finalists.</p>':''}<button class="primary" data-action="confirm-demo" ${b.total>moneyLeft()?'disabled':''}>Confirm demo meal <span>↗</span></button><button class="text-button" data-action="view-finalists">Back to finalists</button>`;}
function orderView(){const o=state.orders.at(-1);return `<div class="bill"><span class="eyebrow">${o.logged>=1?'FOOD LOG UPDATED':'SAMPLE ORDER CONFIRMED'}</span><div class="row total"><span>${o.logged>=1?'Consumed':'Committed spend'}</span><span>${o.logged>=1?'One meal':'₹'+o.total}</span></div><p class="small muted">${o.logged>=1?'Nutrition and opportunities updated. Spending was already recorded.':o.logged>0?'Half logged. The other half is reserved as leftovers.':'Your sample spend is recorded. Nutrition is reserved, not counted as eaten.'}</p></div>${o.logged<1?`<button class="primary" data-action="eat" data-fraction="${1-o.logged}">${o.logged===0?'I ate the whole meal':'Log the remaining half'} <span>✓</span></button>${o.logged===0?'<button class="secondary" data-action="eat" data-fraction="0.5" style="width:100%;margin-top:9px">I ate half · save the rest</button>':''}`:''}<button class="text-button" data-action="next">Plan my next meal</button>`;}
function favoritesView(){const saved=meals.filter(m=>state.saved.includes(m.id));return `<div class="decision-head"><span class="eyebrow">FAMILIAR FEELS GOOD</span><h2>Your little list of go-tos.</h2><p class="small muted">Saved for this demo session. Prices and portions would need a fresh check in the real app.</p></div><div class="go-to-list">${saved.map(m=>`<button class="go-to-item" data-action="favorite-shortlist" data-id="${m.id}"><img src="${image(m)}" alt="Illustrative food photograph"><strong>${m.name}</strong><small>₹${rangeText(m.price)} est. · Tap to shortlist</small></button>`).join('')||'<p class="muted">Tap the heart on a meal card to save a go-to.</p>'}</div><button class="text-button" data-action="browse" style="margin-top:20px">Back to meal discovery</button>`;}
function decision(){if(state.stage==='discover')return discovery();if(state.stage==='favorites')return favoritesView();if(['ready','concealing','shuffling','draw','revealing'].includes(state.stage))return drawView();const m=mealById(state.winner);const headings={revealed:['THE UNIVERSE HAS GOOD TASTE','It’s a meal match.','Chosen from your own finalists. You get the last word.'],review:['LET’S CHECK THE DETAILS','A little clarity before checkout.','A sample bill, with the full basket and its trade-offs.'],ordered:['A MEAL, NOT A MACRO ENTRY','Reserved for your next bite.','Money spent and food eaten are two different things.'],eaten:['A LITTLE LESS TO THINK ABOUT','One meal, logged.','Your daily plan updates with the portion you ate.']};const h=headings[state.stage]||headings.revealed;return `<div class="decision-head"><span class="eyebrow">${h[0]}</span><h2>${h[1]}</h2><p class="small muted">${h[2]}</p></div>${mealCard(m,state.stage)}`;}
function VariantCompanion(){return `<section class="intro"><div><span class="eyebrow">EAT WELL. THINK LESS.</span><h1>Good food.<br>Less <span class="italic">overthinking.</span></h1></div><div><p>You don’t need a perfect schedule.<br>Just a next meal that makes sense for you.</p>${steps()}</div></section><main class="workspace"><aside class="companion-column">${companion()}<div class="little-note"><b>Small choices. A better day.</b>Choose a few meals you like. Let a little luck handle the last decision.</div></aside><section class="decision">${decision()}</section><aside class="today">${tracker()}${finalists()}</aside></main>`;}
function VariantPocket(){return `<main class="pocket"><section class="pocket-intro">${orb(true)}<div><span class="eyebrow" style="color:var(--purple)">YOUR NEXT GOOD THING</span><h1>Hungry? Let’s make<br>this <span class="italic">easy.</span></h1><p class="small muted">Three maybes. One lucky meal.</p><button class="text-button" data-action="check-in">Check in with Hungii ↗</button></div></section><div class="tracker-strip"><div><small>Calories left</small><strong>${rangeText(remaining('cal'),10)}</strong></div><div><small>Rupees left</small><strong>₹${moneyLeft()}</strong></div><div><small>Meals left</small><strong>${state.opportunities} <button data-action="edit-budget" aria-label="Edit daily targets">↗</button></strong></div></div><section class="decision">${decision()}</section>${finalists()}<details class="panel" style="margin-bottom:16px"><summary>Your full daily tracker</summary>${tracker()}</details>${companion()}</main>`;}
function VariantDaybook(){return `<main class="journal"><section class="journal-heading"><div><span class="eyebrow">THE FLEXIBLE FOOD DAY</span><h1>A little plan.<br>A little <span class="italic">serendipity.</span></h1><p>Your goals set the direction. Your cravings get a say.</p>${steps()}</div>${orb(true)}</section><section class="journal-stats"><div><small>Calories remaining</small><strong>${rangeText(remaining('cal'),10)} <small>kcal</small></strong></div><div><small>Protein remaining</small><strong>${rangeText(remaining('protein'))} <small>g</small></strong></div><div><small>Food allowance left</small><strong>₹${moneyLeft()}</strong></div><div><small>Eating opportunities</small><strong>${state.opportunities}</strong></div><div><small>Your day is editable</small><button class="text-button" data-action="edit-budget" style="margin-top:12px">Adjust my plan ↗</button></div></section><div class="journal-work"><section class="decision">${decision()}</section><aside>${finalists()}<details class="panel" style="margin-top:18px"><summary>Your full daily tracker</summary>${tracker()}</details>${companion()}</aside></div></main>`;}
function statePanel(){return `<details><summary>Prototype state · what changed?</summary><p style="margin-top:10px;line-height:1.6">${escapeHTML(state.lastChange)}</p><div class="state-grid"><div><strong>Current step</strong>${escapeHTML(state.stage)}</div><div><strong>Finalists</strong>${state.finalists.map(id=>mealById(id).name).join(', ')||'None'}</div><div><strong>Winner</strong>${state.winner?mealById(state.winner).name:'Not drawn yet'}</div><div><strong>Daily targets</strong>${state.goals.cal} kcal · P ${state.goals.protein}g · C ${state.goals.carbs}g · F ${state.goals.fat}g</div><div><strong>Consumed</strong>${Object.entries(state.intake).map(([k,v])=>`${k}: ${rangeText(v)}`).join(' · ')}</div><div><strong>Allowance / spent / remaining</strong>₹${state.allowance} / ₹${state.spent} / ₹${moneyLeft()}</div><div><strong>Eating opportunities</strong>${state.opportunities}</div><div><strong>Preferences</strong>${[...state.tastes,state.highProtein?'high protein':'',state.vegOnly?'veg only':'',state.cheapOnly?'under ₹250':'',state.fast?'fast delivery':''].filter(Boolean).join(', ')||'Any'}</div><div><strong>Passed this round</strong>${state.passed.map(id=>mealById(id).name).join(', ')||'None'}</div><div><strong>Saved go-tos</strong>${state.saved.map(id=>mealById(id).name).join(', ')||'None'}</div><div><strong>Sample orders and consumption</strong>${state.orders.map(o=>`${mealById(o.meal).name}: ₹${o.total}, ${Math.round(o.logged*100)}% eaten${o.addon?', curd side':''}`).join('; ')||'None'}</div><div><strong>Reserved calories</strong>${rangeText(reserved('cal'),10)} kcal</div></div></details>`;}
function render(){const app=document.getElementById('app');const y=window.scrollY;app.innerHTML=`<div class="variant-${variant}"><header class="app-header"><div class="brand"><span class="brand-symbol">h.</span>hungii<span style="color:var(--purple)">.</span></div><nav class="header-nav" aria-label="Main navigation"><button data-action="browse" class="${state.stage!=='favorites'?'active':''}">Find a meal</button><button data-action="favorites" class="${state.stage==='favorites'?'active':''}">My go-tos <small>${state.saved.length}</small></button><button data-action="edit-budget">My day</button></nav><div class="header-tools"><span class="prototype-label">Prototype · sample data</span><button class="icon-button" data-action="reset" aria-label="Restart prototype" title="Restart prototype">↻</button><span class="avatar" aria-hidden="true">YOU</span></div></header>${variant==='a'?VariantCompanion():variant==='b'?VariantPocket():VariantDaybook()}<footer class="footer"><span>THROWAWAY PROTOTYPE · Fictional meals, nutrition, offers & prices. No real ordering.</span>${statePanel()}</footer><div class="variant-switcher" aria-label="Prototype layout switcher"><button data-action="variant-prev" aria-label="Previous layout">←</button><span><small>LAYOUT </small>${variant.toUpperCase()} · ${names[variant]}</span><button data-action="variant-next" aria-label="Next layout">→</button></div></div>`;if(!isReviewEnvironment)document.querySelector('.variant-switcher')?.remove();bindSwipe();window.scrollTo({top:y,behavior:'instant'});}
function switchVariant(direction){if(!isReviewEnvironment)return;const keys=Object.keys(names);variant=keys[(keys.indexOf(variant)+direction+keys.length)%keys.length];const url=new URL(location.href);url.searchParams.set('variant',variant);window.history.replaceState({},'',url);render();window.scrollTo(0,0);}
function shuffled(ids){const a=[...ids];for(let i=a.length-1;i>0;i--){const limit=Math.floor(4294967296/(i+1))*(i+1);let n;do{n=crypto.getRandomValues(new Uint32Array(1))[0];}while(n>=limit);const j=n%(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
function startShuffle(){if(state.stage!=='ready'||state.finalists.length<2)return;if(isListening)stopListening();snapshot();const epoch=++timerEpoch;state.drawMap=shuffled(state.finalists);state.stage='concealing';state.lastChange='Finalists turned face down. No cart or order changed.';render();setTimeout(()=>{if(epoch!==timerEpoch)return;state.stage='shuffling';state.lastChange='Shuffling the same finalists with equal chances.';render();setTimeout(()=>{if(epoch!==timerEpoch)return;state.stage='draw';state.lastChange='Shuffle complete. Each card is ready to pick.';render();},reducedMotion()?20:1550);},reducedMotion()?20:450);}
function pickCard(index){if(state.stage!=='draw'||index<0||index>=state.drawMap.length)return;const epoch=++timerEpoch;state.chosenIndex=index;state.winner=state.drawMap[index];state.winnerMode='draw';state.stage='revealing';state.lastChange=`Card ${index+1} chosen. Revealing one finalist; nothing ordered.`;render();notify(`Your pick: ${mealById(state.winner).name}`);setTimeout(()=>{if(epoch!==timerEpoch)return;state.stage='revealed';state.lastChange='Winner revealed. Review it or revisit your finalists.';render();document.querySelector('.decision')?.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'});},reducedMotion()?20:850);}
function swipe(direction){if(state.stage!=='discover')return;const m=pool()[0];if(!m)return;snapshot();if(direction==='like'){state.finalists.push(m.id);state.lastChange=`${m.name} shortlisted. ${state.finalists.length} of 3 selected. Nothing ordered.`;if(state.finalists.length===3){state.stage='ready';state.message='Three meals you’d actually eat. Shall we let luck make the last choice?';notify('Your three finalists are ready.');}}else{state.passed.push(m.id);state.lastChange=`Passed on ${m.name}. It won’t return unless you revisit passed meals.`;}render();}
function bindSwipe(){const card=document.getElementById('active-card');if(!card)return;let startX=null,startY=null,dx=0,dragging=false;card.addEventListener('pointerdown',e=>{if(e.target.closest('button,summary,details'))return;startX=e.clientX;startY=e.clientY;dx=0;dragging=false;});card.addEventListener('pointermove',e=>{if(startX===null)return;dx=e.clientX-startX;const dy=e.clientY-startY;if(!dragging&&Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>15){startX=null;return;}if(Math.abs(dx)>12){dragging=true;card.setPointerCapture(e.pointerId);card.style.transform=`translateX(${dx*.65}px) rotate(${dx/25}deg)`;const stamp=card.querySelector('.swipe-stamp');stamp.classList.toggle('pass',dx<0);stamp.textContent=dx>0?'MAYBE!':'NOT TODAY';stamp.style.opacity=Math.min(1,Math.abs(dx)/100);}});function end(e,cancel=false){if(startX===null)return;const shouldSwipe=!cancel&&Math.abs(dx)>85;startX=null;card.style.transform='';card.querySelector('.swipe-stamp').style.opacity=0;if(shouldSwipe)swipe(dx>0?'like':'pass');}card.addEventListener('pointerup',e=>end(e));card.addEventListener('pointercancel',e=>end(e,true));card.addEventListener('pointerleave',e=>{if(!dragging)startX=null;});}
function parseMessage(raw){const text=raw.trim().toLowerCase();if(!text)return;let handled=false,receipt=[];snapshot();const rupees=text.match(/(?:₹|rs\.?\s*|rupees?\s*)(\d+)/)||text.match(/(\d+)\s*(?:rupees?|rs\.?)/);const opp=text.match(/\b([1-8])\s*(?:more\s+)?(?:meals?|eating opportunities)\s*(?:left|remaining)?/);if(rupees){const amount=Number(rupees[1]);if(/left|remaining/.test(text)){state.allowance=state.spent+amount;receipt.push(`Remaining food allowance set to ₹${amount}.`);handled=true;}else if(/daily|allowance|budget/.test(text)){state.allowance=amount;receipt.push(`Daily allowance set to ₹${amount}; ₹${state.spent} already spent.`);handled=true;}else{receipt.push('Is that your daily allowance or money left? Try “₹350 left”.');handled=true;}}if(opp){state.opportunities=Number(opp[1]);receipt.push(`${state.opportunities} eating opportunities left.`);handled=true;}const eggs=text.match(/(?:had|ate|eaten)\s+([1-6]|two|one|three)\s+eggs?/);if(eggs){const count=Number(eggs[1])||({one:1,two:2,three:3}[eggs[1]]);const sample={cal:[65,85],protein:[5,7],carbs:[0,1],fat:[4,6]};for(const k of Object.keys(sample))state.intake[k]=state.intake[k].map((v,i)=>v+sample[k][i]*count);receipt.push(`Logged ${count} eggs using a fictional demo estimate (${65*count}–${85*count} kcal). Opportunities unchanged; edit them if needed.`);handled=true;}const tastes=['spicy','bland','sweet','cheesy','light','filling'].filter(t=>text.includes(t));if(tastes.length){state.tastes=tastes;receipt.push(`Craving updated: ${tastes.join(' + ')}.`);handled=true;}if(/high[ -]?protein|more protein/.test(text)){state.highProtein=true;receipt.push('Protein contribution gets more weight.');handled=true;}if(/veg only|vegetarian/.test(text)){state.vegOnly=true;receipt.push('Vegetarian-only pool enabled.');handled=true;}if(/quick|fast/.test(text)){state.fast=true;receipt.push('Faster delivery gets more weight.');handled=true;}if(!handled){history.pop();state.message='I’m a scripted demo for now. Try “something spicy”, “₹350 left”, “2 meals left”, or “I had 2 eggs”.';state.receipt='No tracker values changed.';}else{state.message=tastes.length?'Got it. Let’s find your kind of food, with room left for later.':'Your day is updated. Plans are allowed to change.';state.receipt=receipt.join(' ');state.lastChange=state.receipt;if(state.finalists.length)state.receipt+=' Your finalists are preserved.';}render();notify(state.receipt);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
  if(action==='variant-prev')return switchVariant(-1);if(action==='variant-next')return switchVariant(1);
  if(action==='pass'||action==='like')return swipe(action);
  if(action==='shuffle')return startShuffle();if(action==='pick')return pickCard(Number(el.dataset.index));
  if(action==='undo'){if(!history.length)return;++timerEpoch;state=history.pop();if(['concealing','shuffling','draw','revealing'].includes(state.stage))state.stage='ready';state.lastChange='Last change undone.';render();notify('Last change undone.');return;}
  if(action==='reset'){++timerEpoch;stopListening();if('speechSynthesis'in window)speechSynthesis.cancel();state=initialState();history=[];render();notify('Fresh sample day.');return;}
  if(action==='filter'){change(()=>{const key=el.dataset.filter;if(key==='spicy'){state.tastes=state.tastes.includes('spicy')?state.tastes.filter(t=>t!=='spicy'):[...state.tastes,'spicy'];}else{const map={protein:'highProtein',cheap:'cheapOnly',veg:'vegOnly',fast:'fast'};state[map[key]]=!state[map[key]];}},'Search preferences updated. Existing finalists unchanged.');return;}
  if(action==='save'){change(()=>{const id=el.dataset.id;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];},'Go-to list updated for this in-memory demo.');notify('Go-to list updated.');return;}
  if(action==='remove'){change(()=>{state.finalists=state.finalists.filter(id=>id!==el.dataset.id);state.stage='discover';state.winner=null;state.drawMap=[];state.addon=false;},'Finalist removed; discovery resumed.');return;}
  if(action==='finalists'||action==='view-finalists'){if(!state.finalists.length)return;++timerEpoch;change(()=>{state.addon=false;if(state.finalists.length===1){state.winner=state.finalists[0];state.winnerMode='manual';state.stage='revealed';}else{state.stage='ready';state.winner=null;}},'Finalists ready for review; no cart changed.');return;}
  if(action==='change-finalists'){++timerEpoch;change(()=>{state.stage='discover';state.winner=null;state.drawMap=[];},'Returned to discovery. Finalists preserved.');return;}
  if(action==='manual-pick'){change(()=>{state.winner=el.dataset.id;state.winnerMode='manual';state.stage='revealed';},'Finalist chosen manually. Nothing ordered.');return;}
  if(action==='review'){change(()=>{state.stage='review';state.addon=false;},'Sample bill displayed. No real cart or payment exists.');return;}
  if(action==='confirm-demo'){if(state.stage!=='review')return;const m=mealById(state.winner),b=sampleBill(m);if(b.total>moneyLeft())return;change(()=>{state.spent+=b.total;state.orders.push({meal:m.id,addon:state.addon,total:b.total,logged:0});state.stage='ordered';state.message='Your sample meal is reserved. Tell me when you eat it, and I’ll update your food log.';},`Demo order committed ₹${b.total}. Nutrition reserved; nothing counted as eaten.`);return;}
  if(action==='eat'){const o=state.orders.at(-1);if(!o||o.logged>=1)return;const fraction=Math.min(Number(el.dataset.fraction),1-o.logged),n=nutrition(mealById(o.meal),o.addon);change(()=>{for(const k of Object.keys(n))state.intake[k]=state.intake[k].map((v,i)=>v+n[k][i]*fraction);o.logged+=fraction;state.opportunities=Math.max(0,state.opportunities-1);state.stage='eaten';state.message='Logged. Your next choice will work with the day you’re actually having.';},`${Math.round(fraction*100)}% of the sample meal logged. Spending unchanged. One eating opportunity used.`);return;}
  if(action==='next'){change(()=>{state.stage='discover';state.finalists=[];state.passed=[];state.winner=null;state.drawMap=[];state.addon=false;},'New meal decision. Intake, spending, saved meals and reservations preserved.');return;}
  if(action==='revisit'){change(()=>{state.passed=[];},'Passed meals are available again by your request.');return;}
  if(action==='favorites'){change(()=>{state.stage='favorites';},'Viewing saved go-to meals.');return;}
  if(action==='browse'){++timerEpoch;change(()=>{state.stage=state.finalists.length>=3?'ready':'discover';},'Returned to the current meal decision.');return;}
  if(action==='favorite-shortlist'){const m=mealById(el.dataset.id);if(state.finalists.includes(m.id))return notify('Already in your finalists.');if(state.finalists.length>=3)return notify('Your three slots are full. Remove one to make room.');if(state.vegOnly&&!m.veg||m.price[0]>moneyLeft()||state.cheapOnly&&m.price[1]>250)return notify('This go-to does not fit your current filters. Update your plan first.');change(()=>{state.finalists.push(m.id);state.stage=state.finalists.length===3?'ready':'discover';},`${m.name} added from go-tos.`);return;}
  if(action==='edit-budget'){const form=document.getElementById('budget-form');for(const [k,v]of Object.entries(state.goals))form.elements.namedItem(k).value=v;form.elements.namedItem('allowance').value=state.allowance;form.elements.namedItem('opportunities').value=Math.max(1,state.opportunities);document.getElementById('budget-dialog').showModal();return;}
  if(action==='close-budget')return document.getElementById('budget-dialog').close();
  if(action==='check-in'){document.querySelector('.companion')?.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'start'});document.querySelector('.chat-form input')?.focus({preventScroll:true});return;}
  if(action==='example')return parseMessage(el.dataset.text);if(action==='mic')return isListening?stopListening():startListening();if(action==='speak')return speakDay();
});
document.addEventListener('submit',e=>{if(e.target.matches('.chat-form')){e.preventDefault();parseMessage(e.target.querySelector('input').value);}if(e.target.id==='budget-form'){e.preventDefault();const data=new FormData(e.target);change(()=>{for(const k of Object.keys(state.goals))state.goals[k]=Number(data.get(k));state.allowance=Number(data.get('allowance'));state.opportunities=Number(data.get('opportunities'));state.message='Your plan is updated. A good day has room to change.';},'Daily targets and allowance updated. Existing consumption and spending preserved.');document.getElementById('budget-dialog').close();notify('Your day is updated.');}});
document.addEventListener('change',e=>{if(e.target.id==='offer-side'){change(()=>{state.addon=e.target.checked;},'Sample side toggled. Full basket nutrition and payable amount recomputed.');}});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable],dialog'))return;if(e.key==='ArrowLeft'){e.preventDefault();switchVariant(-1);}if(e.key==='ArrowRight'){e.preventDefault();switchVariant(1);}});
function cleanMic(){if(meterFrame)cancelAnimationFrame(meterFrame);meterFrame=null;micStream?.getTracks().forEach(t=>t.stop());micStream=null;audioContext?.close().catch(()=>{});audioContext=null;document.querySelectorAll('.orb').forEach(el=>el.style.removeProperty('--voice'));}
function stopListening(){recognition?.stop();isListening=false;cleanMic();render();}
async function meter(){try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!isListening){stream.getTracks().forEach(t=>t.stop());return;}micStream=stream;audioContext=new(window.AudioContext||window.webkitAudioContext)();const analyser=audioContext.createAnalyser();analyser.fftSize=256;audioContext.createMediaStreamSource(stream).connect(analyser);const data=new Uint8Array(analyser.frequencyBinCount);function tick(){if(!isListening)return;analyser.getByteFrequencyData(data);const energy=data.reduce((a,b)=>a+b,0)/data.length/100;document.querySelectorAll('.orb').forEach(el=>el.style.setProperty('--voice',Math.min(1,energy)));meterFrame=requestAnimationFrame(tick);}tick();}catch{/* Voice recognition can still work without the amplitude effect. */}}
function startListening(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return notify('Voice recognition isn’t available in this browser. Type to the orb instead.');recognition=new SR();recognition.lang='en-IN';recognition.interimResults=false;recognition.continuous=false;recognition.onstart=()=>{isListening=true;render();meter();notify('Listening. Tell me your craving or a tracker update.');};recognition.onresult=e=>{parseMessage(e.results[0][0].transcript);};recognition.onerror=()=>{notify('Voice didn’t connect. You can still type your update.');};recognition.onend=()=>{isListening=false;cleanMic();render();};try{recognition.start();}catch{notify('Voice is unavailable right now. Try typing instead.');}}
function speakDay(){if(!('speechSynthesis'in window))return notify('Audio isn’t supported here. Your tracker is available on screen.');speechSynthesis.cancel();const text=`Hey, hungry human. You’ve logged approximately ${rangeText(state.intake.cal,10).replace('–',' to ')} calories, ${rangeText(state.intake.protein).replace('–',' to ')} grams of protein, ${rangeText(state.intake.carbs).replace('–',' to ')} grams of carbs, and ${rangeText(state.intake.fat).replace('–',' to ')} grams of fat. You have approximately ${rangeText(remaining('cal'),10).replace('–',' to ')} calories left, ${moneyLeft()} rupees left, and ${state.opportunities} eating opportunities. What do you feel like having?`;const utterance=new SpeechSynthesisUtterance(text);utterance.rate=.95;utterance.onstart=()=>{isSpeaking=true;render();};utterance.onend=utterance.onerror=()=>{isSpeaking=false;render();};speechSynthesis.speak(utterance);}
window.addEventListener('pagehide',()=>{cleanMic();if('speechSynthesis'in window)speechSynthesis.cancel();});
render();
